import{_ as o,l,o as e,c as i,v as t,p as s,x as r,d as p,i as d,S as P}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"参数化复杂性 FPT","description":"","frontmatter":{"title":"参数化复杂性 FPT","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/fpt-parameterized.md","filePath":"cs/fpt-parameterized.md","lastUpdated":1789023840000}'),k={name:"cs/fpt-parameterized.md"};function T(c,a,h,f,m,F){const n=l("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="参数化复杂性-fpt" tabindex="-1">参数化复杂性 FPT <a class="header-anchor" href="#参数化复杂性-fpt" aria-label="Permalink to &quot;参数化复杂性 FPT&quot;">​</a></h1><div class="epigraph"><p>把参数 $k$ 从输入长度 $n$ 里拆出来：$f(k)n^{O(1)}$ 为 FPT；若必须 $n^{g(k)}$，则停在 XP 或 W 层级，顶点覆盖与团因此分家。</p><footer>—— 据 Downey and Fellows, Parameterized Complexity；Cygan et al., Parameterized Algorithms 整理</footer></div><p>上一课<a href="/cs/circuit-complexity">电路</a> 仍对 \\(n\\) 最坏。主干 NPC 把顶点覆盖与团捆在一起。缺口是<strong>参数</strong>：覆盖大小 \\(k\\) 小时，覆盖有 \\(1.28^k n\\) 一类算法，团没有已知的 \\(n^{o(k)}\\)。FPT vs W[1]。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>参数化问题 \\((x,k)\\)。FPT：时间 \\(f(k)|x|^{O(1)}\\)，\\(f\\) 任意可计算（通常指数）。核：多项式时间压到 \\(g(k)\\) 规模，再蛮力。顶点覆盖：搜两边或核 \\(2k\\)。团、独立集对参数解大小是 W[1] 完全：相信不在 FPT。W 层级用短路电路或权 \\(k\\) 的 SAT 切片定义，本课要形状不写完全性证明。</p><p>XP：\\(n^{g(k)}\\)，包含 FPT。FPT \\(\\neq\\) XP 若时间层级一类假设。ETH（指数时间假设）把 \\(2^{o(n)}\\) 的 3SAT 排除，用来钉 FPT 的 \\(f(k)\\) 底。</p><h3 id="不是「-很小就多项式」" tabindex="-1">不是「\\(k\\) 很小就多项式」 <a class="header-anchor" href="#不是「-很小就多项式」" aria-label="Permalink to &quot;不是「$k$ 很小就多项式」&quot;">​</a></h3><p>\\(n^k\\) 当 \\(k=\\log n\\) 已超多项式。FPT 要求 \\(n\\) 的指数与 \\(k\\) 无关。把 \\(k\\) 取成 \\(n\\) 就退回古典。</p><p><span class="marginnote">Downey–Fellows 开创。Cygan 等是算法书。本课不把树宽算法写完，点名：树宽 \\(w\\) 时许多问题 \\(2^{O(w)}n\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对顶点覆盖给搜树或核的思路。对团说明为何蛮力 \\(n^k\\) 停在 XP。声明：同一古典 NPC 问题，换参数（解大小、树宽、删除数）可进 FPT 或 W 难。不要对所有 NPC 宣称「参数化之后就好」。</p>',11)),(e(),s(P,null,{default:r(()=>[d(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20NPC%5B%22%E5%8F%A4%E5%85%B8%20NP%20%E5%AE%8C%E5%85%A8%22%5D%20--%3E%20PAR%5B%22%E9%80%89%E5%AE%9A%E5%8F%82%E6%95%B0%20k%22%5D%0A%20%20PAR%20--%3E%20FPT%5B%22f(k)%20n%5EO(1)%22%5D%0A%20%20PAR%20--%3E%20W1%5B%22W1%20%E5%AE%8C%E5%85%A8%20%2F%20%E9%9D%9E%20FPT%20%E4%BF%A1%E5%BF%B5%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>FPT 把组合爆炸关进 \\(k\\)。实践：编译、生物网络里 \\(k\\) 真小才有意义。W[1] 完全是参数世界的 SAT。与近似、随机正交：一个问题可以 FPT 但不可近似，或反之。</p><p>核大小下界（多项式核是否存在）是另一层，本课点名。</p><p>核是 FPT 的证书：压到 \\(g(k)\\) 再 \\(2^{g(k)}\\) 蛮力仍 FPT。多项式核是否存在另有下界技术（或门）。树宽 \\(w\\) 时，许多 MSO 性质 \\(f(w)n\\)，Courcelle，点名。把 \\(k\\) 取成解大小，顶点覆盖与团分家——同一 NPC 标签，参数化后不是一类。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 W[1] 完全，不引入 MSO / Courcelle 全文。不把机器学习的超参当 \\(k\\)。后课默认：谈「\\(k\\) 小时」，先问 FPT 还是 \\(n^k\\)。下一课平均情形与单向函数。</p><p>FPT 要求 \\(n\\) 的指数与 \\(k\\) 脱钩；\\(n^k\\) 停在 XP。ETH 用来钉 \\(f(k)\\) 不能再降到 \\(2^{o(k)}\\) 一类。同一古典 NPC 问题换参数（树宽 vs 解大小）可进 FPT 或 W 难。</p><p>上一课留下的缺口在本课收口；「参数化复杂性 FPT」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FPT \\(= f(k)n^{O(1)}\\)；顶点覆盖典型，团对解大小不是。</li><li>W[1] 是参数化硬度；ETH 钉 \\(f(k)\\) 底。</li><li>参数选择决定类，不是问题名字决定。</li><li>出处：Downey and Fellows；Cygan et al.。</li></ul>',10))])}const E=o(k,[["render",T]]);export{u as __pageData,E as default};
